/**
 * Mimics `@koa/router` and friends: the package's entry point exposes its type ONLY as the
 * default export. There is no named `Router` binding to import, so nothing a generated file
 * writes as `import type { … } from "@vendor/router"` can ever bind it.
 */
export default class Router {
  use(path: string): this;
  routes(): (ctx: unknown) => void;
}
